using System.Text;
using System.Text.Json;
using AssetBlock.Infrastructure.Persistence;

namespace AssetBlock.Infrastructure.Tests.Persistence;

/// <summary>
/// Cross-language contract for the canonical hash form. The vectors are generated by the analysis
/// service (services/code-analysis/tools/emit_canonical_vectors.py), so a .NET regression that
/// changes escaping, key order or numeric handling fails here rather than in production digests.
/// </summary>
public class CanonicalJsonContractTests
{
    public static TheoryData<string, string, string, string> Vectors
    {
        get
        {
            var data = new TheoryData<string, string, string, string>();
            foreach (GoldenVector vector in LoadVectors())
            {
                data.Add(vector.Name, vector.Document, vector.CanonicalUtf8, vector.Digest);
            }

            return data;
        }
    }

    [Theory]
    [MemberData(nameof(Vectors))]
    public void DigestOf_WhenVectorFromAnalysisService_ShouldMatchServiceBytesAndDigest(
        string name,
        string document,
        string expectedCanonicalUtf8,
        string expectedDigest)
    {
        using var parsed = JsonDocument.Parse(document);

        CanonicalJson.CanonicalizeToString(parsed.RootElement).Should().Be(
            expectedCanonicalUtf8,
            because: $"{name} must canonicalize byte for byte like the analysis service");

        CanonicalJson.Sha256Hex(parsed.RootElement).Should().Be(expectedDigest);
    }

    [Fact]
    public void Canonicalize_WhenNonCanonicalNumberToken_ShouldPreserveTokenVerbatim()
    {
        // No silent numeric normalization: the token is hashed exactly as received.
        const string document = "{\"v\":1.10}";
        using var parsed = JsonDocument.Parse(document);

        CanonicalJson.CanonicalizeToString(parsed.RootElement).Should().Be("{\"v\":1.10}\n");
    }

    [Fact]
    public void Canonicalize_WhenExponentToken_ShouldPreserveTokenVerbatim()
    {
        const string document = "{\"v\":1E10}";
        using var parsed = JsonDocument.Parse(document);

        CanonicalJson.CanonicalizeToString(parsed.RootElement).Should().Be("{\"v\":1E10}\n");
    }

    [Fact]
    public void Canonicalize_WhenDuplicateProperty_ShouldReject()
    {
        const string document = "{\"a\":1,\"a\":2}";
        using var parsed = JsonDocument.Parse(document);

        Action act = () => CanonicalJson.Canonicalize(parsed.RootElement);

        act.Should().Throw<CanonicalJsonException>();
    }

    [Fact]
    public void DigestOf_WhenUnpairedSurrogate_ShouldReject()
    {
        var value = CanonicalValue.Object(("v", CanonicalValue.Text("\ud800abc")));

        Action act = () => CanonicalJson.DigestOf(value);

        act.Should().Throw<CanonicalJsonException>();
    }

    [Fact]
    public void DigestOf_WhenNonJsonNumberToken_ShouldReject()
    {
        var value = CanonicalValue.Object(("v", CanonicalValue.Number(double.NaN)));

        Action act = () => CanonicalJson.DigestOf(value);

        act.Should().Throw<CanonicalJsonException>();
    }

    [Fact]
    public void Canonicalize_WhenCyrillic_ShouldNotEscapeNonAscii()
    {
        const string document = "{\"scope\":\"src/модуль.py\"}";
        using var parsed = JsonDocument.Parse(document);

        var canonical = CanonicalJson.CanonicalizeToString(parsed.RootElement);

        canonical.Should().Be("{\"scope\":\"src/модуль.py\"}\n");
        canonical.Should().NotContain("\\u");
    }

    [Fact]
    public void Canonicalize_WhenHtmlSensitive_ShouldNotEscape()
    {
        const string document = "{\"h\":\"<a href='x'>&amp;</a>\"}";
        using var parsed = JsonDocument.Parse(document);

        CanonicalJson.CanonicalizeToString(parsed.RootElement).Should().Be(document + "\n");
    }

    [Fact]
    public void Canonicalize_WhenNonBmp_ShouldEncodeAsUtf8()
    {
        const string document = "{\"e\":\"\U0001F512\"}";
        using var parsed = JsonDocument.Parse(document);

        var bytes = CanonicalJson.Canonicalize(parsed.RootElement);

        Encoding.UTF8.GetString(bytes).Should().Be("{\"e\":\"\U0001F512\"}\n");
        bytes.Should().NotContain((byte)'\\');
    }

    private static IReadOnlyList<GoldenVector> LoadVectors()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "canonical_vectors.json");
        using FileStream stream = File.OpenRead(path);
        using var parsed = JsonDocument.Parse(stream);

        return parsed.RootElement.EnumerateArray()
            .Select(v => new GoldenVector(
                v.GetProperty("name").GetString()!,
                v.GetProperty("document").GetString()!,
                v.GetProperty("canonicalUtf8").GetString()!,
                v.GetProperty("digest").GetString()!))
            .ToList();
    }

    private sealed record GoldenVector(string Name, string Document, string CanonicalUtf8, string Digest);
}
